#ifndef SD_POPUP_H
#define SD_POPUP_H

#include "ui_types.h"
#include "status_view.h"

/* -----------------------------------------------------------------------
 * sd_popup.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29 Oct 2026 for Tony's display/UI subsystem (best-ui).
 * BJT2 Sound Modulating Toy — "No SD Card" Pop-up (best-ui)
 * Subsystem: Display/UI (Tony). Generative AI was used to assist.
 *
 * REC or PLAY with no usable card used to look as if it had worked: the
 * UI showed "Recording" until Jack's refusal came back. Now the firmware
 * checks Jack's newest status first. When the card cannot take it,
 * nothing starts: a big red pop-up over the body says why for 3 s and
 * the fault beep sounds. A refusal from Jack himself (ack ok = 0) opens
 * it too.
 *
 *      +------------------+
 *      |    NO SD CARD    |
 *      |  Insert a card   |
 *      |    to record     |
 *      +------------------+
 *
 * The pop-up does not take the input that closes it: REC again once a
 * card is in starts the recording. Only a tap on the box itself is used
 * up, so nothing hidden under it (a Home tile, a Volume button) acts.
 *
 * This module decides, words and times it. No SPI, no HAL: tony_ui.c
 * draws the box, sends the beep and draws the screen under it again.
 * ----------------------------------------------------------------------- */

/* ===================================================================
 * WHAT A STEP STARTS
 * The transitions the firmware turns into RECORD_START and PLAY_START.
 * =================================================================== */
typedef enum {
    SDP_START_NONE = 0,     /* Nothing starts                              */
    SDP_START_RECORD,       /* Into RECORDING from any other state         */
    SDP_START_PLAY,         /* From IDLE into PLAYING (not a resume)       */
} sdp_start_t;

/* ===================================================================
 * WHY
 * The same first-match order as the SD chip and the footer's refusal
 * notice (status_view.h), so the three always agree.
 * =================================================================== */
typedef enum {
    SDP_OK = 0,             /* Nothing in the way (or only Jack can tell)  */
    SDP_ON_PC,              /* Card handed to a PC over USB                */
    SDP_NO_CARD,            /* No card in the slot                         */
    SDP_NO_FILES,           /* PLAY, but no recordings on the card         */
    SDP_FULL,               /* Card full                                   */
    SDP_NOT_READY,          /* Card just put in, not mounted yet           */
    SDP_CARD_ERROR,         /* Card in the slot that cannot be used        */
    SDP_FAILED,             /* Jack refused though the status looked fine  */
    SDP_REASON_COUNT        /* Sentinel                                    */
} sdp_reason_t;

#define SDP_SHOW_MS         3000U   /* How long it shows by itself        */
#define SDP_LINES           3U      /* Text lines in the box              */
#define SDP_TEXT_W          17U     /* Widest line, characters: size 2,   */
                                    /* 204 px inside the 220 px box       */

/* The box over the body (tony_ui.c draws it, sdp_tap_on_box() hits it):
 * x 10..229, y 112..197. On the Record screen the start row (y 72..101)
 * stays in view above it. Its edges pass between lines of text on every
 * screen, so no line is cut in two: Home's top tile labels end at y 110,
 * the Battery screen's fourth line starts at 202, the Play screen's file
 * name at 208. */
#define SDP_BOX_X           10U
#define SDP_BOX_Y           112U
#define SDP_BOX_W           220U
#define SDP_BOX_H           86U

_Static_assert(SDP_BOX_Y >= MENU_Y0 && SDP_BOX_Y + SDP_BOX_H <= STATUS_BAR_Y &&
               SDP_BOX_X + SDP_BOX_W <= SCREEN_W,
               "the pop-up must stay inside the body");

/* The pop-up as it should be on the panel (tony_ui.c keeps one). */
typedef struct {
    bool         open;              /* Showing                            */
    bool         record;            /* REC did nothing; false: PLAY       */
    sdp_reason_t reason;            /* Never SDP_OK while open            */
    ui_screen_t  screen;            /* The screen it covers               */
    uint32_t     until_ms;          /* Tick count it closes at by itself  */
} sd_popup_t;

/**
 * sdp_start_of
 * What one step of the UI starts, from the state before and after it:
 *   after RECORDING, before anything else          SDP_START_RECORD
 *   after PLAYING, before IDLE                     SDP_START_PLAY
 *   anything else (stop, pause, resume, a replay)  SDP_START_NONE
 * A replay restarts a file that is already playing: the card is in use,
 * so there is nothing to check.
 *
 * @param before  State before the event (NULL: SDP_START_NONE).
 * @param after   State after ui_process_event (NULL: SDP_START_NONE).
 */
sdp_start_t sdp_start_of(const ui_state_t *before, const ui_state_t *after);

/**
 * sdp_precheck
 * Can the card take a REC or PLAY start now? From Jack's newest status,
 * first match wins:
 *   no status yet (NULL sd too)    SDP_OK          (Jack decides)
 *   USB-MSC mode                   SDP_ON_PC
 *   recording, playing, paused,    SDP_OK          (the card is in use;
 *   preparing or fx_busy                            the UI stops it first,
 *                                                   Jack drops an effect job)
 *   no card                        SDP_NO_CARD
 *   mounted                        SDP_OK, but PLAY with file_count 0
 *                                  is SDP_NO_FILES
 *   text "Card Full"               SDP_FULL
 *   text "Card Not Ready"          SDP_NOT_READY
 *   anything else                  SDP_CARD_ERROR
 * So for an idle card it refuses exactly what Jack would refuse for the
 * card (he records only on a mounted card, and plays only with files).
 *
 * @param record      true: REC; false: PLAY.
 * @param sd          Storage status, or NULL (= none yet).
 * @param file_count  Recordings on the card (Jack's status): all of them,
 *                    so a uint16_t (256 files must not read as 0).
 */
sdp_reason_t sdp_precheck(bool record, const sv_sd_in_t *sd, uint16_t file_count);

/**
 * sdp_refusal_reason
 * Why Jack refused a start (his ack ok = 0), worded from the status he
 * published just before it: sdp_precheck()'s reason, or SDP_FAILED when
 * that status shows nothing wrong (one file would not open, he was still
 * busy, no status had come yet). The same reason as the footer notice
 * (sv_refusal_text) gives, SDP_FAILED being its "TRY AGAIN".
 */
sdp_reason_t sdp_refusal_reason(bool record, const sv_sd_in_t *sd, uint16_t file_count);

/**
 * sdp_line
 * Line 0, 1 or 2 of the pop-up: what is wrong (upper case), then what to
 * do. Each text is at most SDP_TEXT_W characters; a line can be "".
 *   SDP_NO_CARD   "NO SD CARD" / "Insert a card" / "to record" or "to play"
 *   SDP_ON_PC     "SD CARD ON PC" / "Unplug the USB" / "to record" or "to play"
 *   SDP_NO_FILES  "NO RECORDINGS" / "Press REC to" / "record one"
 *   SDP_FULL      "SD CARD FULL" / "Free some space" / "on a PC"
 *   SDP_NOT_READY "SD NOT READY" / "Wait a moment" / "and try again"
 *   SDP_CARD_ERROR "SD CARD ERROR" / "Re-insert it, or" / "format as FAT32"
 *   SDP_FAILED    "COULD NOT RECORD" or "COULD NOT PLAY" / "Please try again" / ""
 * SDP_OK, a reason out of range or a line past 2 gives "".
 *
 * @return  A constant text, never NULL.
 */
const char *sdp_line(sdp_reason_t reason, bool record, uint8_t line);

/**
 * sdp_init
 * Closed. NULL: nothing happens.
 */
void sdp_init(sd_popup_t *p);

/**
 * sdp_open
 * Opens the pop-up over screen until now_ms + SDP_SHOW_MS, or replaces
 * the one showing (new words, a new 3 s). Nothing changes, and false is
 * returned, for SDP_OK or a reason out of range, and over the fault or
 * debug screen, where it would hide what they show.
 *
 * @return  true if it opened (the firmware then beeps once).
 */
bool sdp_open(sd_popup_t *p, sdp_reason_t reason, bool record,
              ui_screen_t screen, uint32_t now_ms);

/**
 * sdp_refuse
 * A start that sdp_precheck() refused: nothing starts. The step that made
 * it is undone, s going back to the screen and transport it had before
 * (no "Recording" moment), and the pop-up opens over that screen, the one
 * the UI stays on. Opened over the screen the step went to (Record or
 * Play), the next sdp_update() would close it before it was ever drawn.
 * SDP_OK, a reason out of range or a NULL s changes nothing.
 *
 * @param p         The pop-up (NULL: s is still put back, nothing opens).
 * @param why       sdp_precheck()'s reason.
 * @param record    true: REC did nothing; false: PLAY.
 * @param s         State after ui_process_event(); put back.
 * @param screen    The screen before the step: s stays on it.
 * @param playback  The transport before the step.
 * @param now_ms    Tick count.
 * @return  sdp_open()'s result: true if it opened (the firmware then
 *          beeps once).
 */
bool sdp_refuse(sd_popup_t *p, sdp_reason_t why, bool record, ui_state_t *s,
                ui_screen_t screen, playback_state_t playback, uint32_t now_ms);

/**
 * sdp_close_on_input
 * Any input (button, encoder, a tap off the box) closes it. The input is
 * not used up: the firmware still hands it to the state machine.
 *
 * @return  true if it was open (the screen under it is drawn again).
 */
bool sdp_close_on_input(sd_popup_t *p);

/**
 * sdp_tap_on_box
 * A tap at screen pixel (x, y). On the box of an open pop-up it closes it
 * and returns true: the tap is used up, so what is hidden under the box
 * does not act. Anywhere else, or with no pop-up, it changes nothing and
 * returns false (the tap is then an input like any other).
 */
bool sdp_tap_on_box(sd_popup_t *p, uint16_t x, uint16_t y);

/**
 * sdp_update
 * Called on every pass: closes it once SDP_SHOW_MS have gone by (also
 * across the 32-bit tick wrap) or once the screen is not the one it
 * covers (a fault screen, a screen change).
 *
 * @return  true if it closed now.
 */
bool sdp_update(sd_popup_t *p, ui_screen_t screen, uint32_t now_ms);

#endif /* SD_POPUP_H */
